if(!defined('ROBW_OAUTH_LOCAL_TEST')||!ROBW_OAUTH_LOCAL_TEST)return;
add_action('template_redirect',function(){if(parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH)!=='/__test__/state')return;if(!is_user_logged_in()||$_SERVER['REQUEST_METHOD']!=='POST'){status_header(403);exit;}$action=$_POST['action']??'';if($action==='expire'){$kind=$_POST['kind']??'';$key=$_POST['key']??'';if(!in_array($kind,['access','refresh','codes','families'],true)){status_header(400);exit;}$uid=get_current_user_id();RobwOAuthDB::mutate(function(&$s)use($kind,$key,$uid){if(($s[$kind][$key]['user_id']??null)!==$uid)throw new RuntimeException('Fixture owner mismatch');$s[$kind][$key]['expires']=time()-2;});}elseif($action==='role'){if(!current_user_can('manage_options')){status_header(403);exit;}$user=get_user_by('login','alice');$user->set_role(($_POST['role']??'')==='subscriber'?'subscriber':'');}elseif($action==='hash-check'){$uid=get_current_user_id();[$raw,$s]=RobwOAuthDB::read();$key=$_POST['key']??'';$r=$s['access'][$key]??null;if(!$r||$r['user_id']!==$uid){status_header(403);exit;}header('Content-Type: application/json');echo json_encode(['hash_key_present'=>isset($s['access'][$key]),'access_record_keys'=>array_keys($r)]);exit;}else{status_header(400);exit;}header('Content-Type: application/json');echo '{}';exit;},-200);
